    results = []

    for i in range(n):
        suffix = s[i:]
        stack = []
        for j in range(len(suffix) - 1):
            if suffix[j] == suffix[j + 1]:
                stack.append((j, j + 1))

        while stack:
            idx1, idx2 = stack.pop()
            if 0 <= idx1 < len(suffix) - 1 and suffix[idx1] == suffix[idx1 + 1]:
                suffix = suffix[:idx1] + suffix[idx1 + 2:]
                if idx1 > 0 and idx1 - 1 not in stack:
